static const uint64_t demo_a5_free = UINT64_C(0xffffd00000000000);
static int demo_validate_a5_class(void) {
    for(int i=0;i<118;++i) {
        uint64_t s=demo_a5_roots[i];
        if(s1_init(6615,s)!=UINT64_C(0x8e5caae000000000)) return 0;
        for(int bit=0;bit<64;++bit) if((demo_a5_free>>bit)&1)
            if(s1_init(6615,s|(UINT64_C(1)<<bit))!=UINT64_C(0x8e5caae000000000)) return 0;
    }
    return 1;
}

static int demo_source_validation(void) {
    if(smhasher3_verification(64)!=0xADDE79B3u || smhasher3_verification(128)!=0x89406B11u) return 0; return demo_validate_a5_class();
}
static void demo_digest(int i,const uint8_t *m,size_t n,const uint64_t key[4],uint64_t out[4]) {
    if(demo_pairs[i].bits==128) a5hash128(m,n,key[0],out,out+1); else out[0]=a5hash64(m,n,key[0]);
}
static int demo_class_key(int i,uint64_t state[4],uint64_t key[4]) {
    uint64_t r;
    do { r=demo_next(state); } while(r < (uint64_t)(-UINT64_C(118)) % 118);
    key[0] = demo_a5_roots[r % 118] | (key[0] & demo_a5_free);
    return s1_init(6615,key[0]) == UINT64_C(0x8e5caae000000000);
}
static void demo_seed_key(uint64_t seed,uint64_t key[4]) { key[0]=seed; }
